export type Sale = typeof sales.$inferSelect
export type NewSale = typeof sales.$inferInsert

/** Line items for sales — immutable snapshot at time of payment */
export const saleLineItems = sqliteTable('sale_line_items', {
  id: text('id').primaryKey(),
  saleId: text('sale_id').notNull().references(() => sales.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  saleIdIdx: index('sale_line_items_sale_id_idx').on(table.saleId),
  ...lineItemChecks(),
}))

export type SaleLineItem = typeof saleLineItems.$inferSelect
export type NewSaleLineItem = typeof saleLineItems.$inferInsert

